// Приводим данные Error Trigger к одной строке лога.
// Ошибка в обычной ноде приходит в $json.execution, ошибка в триггере — в $json.trigger.
const CATEGORIES = [
  ['timeout', /timeout|timed out|etimedout|econnaborted/],
  ['invalid_token', /\b401\b|\b403\b|unauthori[sz]ed|forbidden|invalid.*(api key|token|credential)|authentication/],
  ['rate_limit', /\b429\b|rate.?limit|too many requests|overloaded|quota/],
  ['invalid_json', /json/],
  ['empty_response', /empty|no output|no response|undefined/],
  ['telegram', /telegram|chat not found|bot was blocked|message is too long|parse entities/],
];

return $input.all().map(({ json }) => {
  const execution = json.execution ?? {};
  const error = execution.error ?? json.trigger?.error ?? {};
  const message = String(error.message ?? 'Unknown error');
  const text = `${message} ${error.description ?? ''}`.toLowerCase();
  const errorType = CATEGORIES.find(([, re]) => re.test(text))?.[0] ?? 'other';

  return {
    json: {
      timestamp: $now.toFormat('yyyy-MM-dd HH:mm:ss'),
      status: 'error',
      workflow_id: json.workflow?.id ?? '',
      workflow_name: json.workflow?.name ?? '',
      node_name: execution.lastNodeExecuted ?? error.node?.name ?? 'trigger',
      execution_id: execution.id ?? '',
      execution_url: execution.url ?? '',
      mode: execution.mode ?? json.trigger?.mode ?? '',
      error_type: errorType,
      error_message: message.slice(0, 500),
      error_stack: String(error.stack ?? '').slice(0, 2000),
    },
  };
});

